      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Imidafenacin, an imidazole-containing drug, has an absolute oral bioavailability of 57.8% in healthy subjects, well above the 20% threshold and supportive of high bioavailability.",
